import { Alert, Box, Chip, Grid, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import dayjs from 'dayjs';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import CalendarTodayOutlinedIcon from '@mui/icons-material/CalendarTodayOutlined';
import PhoneOutlinedIcon from '@mui/icons-material/PhoneOutlined';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import BadgeOutlinedIcon from '@mui/icons-material/BadgeOutlined';
import { IPatientCard } from '../../../../core/Interface/patient.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

const PatientBasicCard = ({
  patientNumber,
  name,
  mobile,
  address,
  message,
  age,
}: IPatientCard) => (
  <Grid
    item
    lg={4}
    sm={12}
    xs={12}
  >
    <Box
      sx={{
        background: '#fff',
        border: `1px solid ${alpha(TEAL, 0.18)}`,
        borderRadius: '12px',
        boxShadow: `0 4px 24px ${alpha(NAVY, 0.06)}`,
        height: '100%',
        minHeight: 320,
        overflow: 'hidden',
      }}
    >
      {/* top accent bar */}
      <Box sx={{ background: `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`, height: 3 }} />

      {/* patient avatar area */}
      <Box
        sx={{
          alignItems: 'center',
          background: `linear-gradient(135deg, ${alpha(TEAL, 0.06)} 0%, ${alpha(MID, 0.04)} 100%)`,
          borderBottom: `1px solid ${alpha(TEAL, 0.1)}`,
          display: 'flex',
          flexDirection: 'column',
          gap: 1,
          pb: 2,
          pt: 2.5,
        }}
      >
        <Box
          sx={{
            alignItems: 'center',
            background: name
              ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
              : alpha(NAVY, 0.08),
            borderRadius: '50%',
            display: 'flex',
            height: 64,
            justifyContent: 'center',
            width: 64,
          }}
        >
          <PersonOutlineIcon sx={{ color: name ? '#fff' : alpha(NAVY, 0.3), fontSize: 32 }} />
        </Box>

        {name ? (
          <>
            {/* eslint-disable-next-line max-len */}
            <Typography sx={{ color: NAVY, fontWeight: 800, fontSize: 16, lineHeight: 1.2 }}>
              {name}
            </Typography>
            <Chip
              label={`ID: ${patientNumber}`}
              size="small"
              sx={{
                background: alpha(TEAL, 0.1),
                border: `1px solid ${alpha(TEAL, 0.25)}`,
                color: TEAL,
                fontSize: 11,
                fontWeight: 700,
              }}
            />
          </>
        ) : (
          <Typography
            sx={{ color: alpha(NAVY, 0.35), fontSize: 13, fontWeight: 500 }}
          >
            No patient selected
          </Typography>
        )}
      </Box>

      {/* details / state */}
      <Box sx={{ px: 2.5, pt: 2, pb: 2.5 }}>
        {!message && !name && (
          <Alert
            severity="info"
            sx={{ borderRadius: '8px', fontSize: 13 }}
            variant="outlined"
          >
            Search and find the patient
          </Alert>
        )}

        {!name && message && (
          <Alert
            severity="warning"
            sx={{ borderRadius: '8px', fontSize: 13 }}
            variant="outlined"
          >
            {message}
          </Alert>
        )}

        {name && (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
            <InfoRow
              // eslint-disable-next-line max-len
              icon={<CalendarTodayOutlinedIcon sx={{ fontSize: 14, color: TEAL }} />}
              label="Date"
              value={dayjs(new Date()).format('MMMM D, YYYY')}
            />
            <InfoRow
              icon={<BadgeOutlinedIcon sx={{ fontSize: 14, color: TEAL }} />}
              label="Age"
              value={age ? String(age) : '—'}
            />
            <InfoRow
              icon={<PhoneOutlinedIcon sx={{ fontSize: 14, color: TEAL }} />}
              label="Mobile"
              value={mobile || '—'}
            />
            <InfoRow
              icon={<HomeOutlinedIcon sx={{ fontSize: 14, color: TEAL }} />}
              label="Address"
              value={address || '—'}
            />
            {message && (
              <Alert
                severity="success"
                sx={{ borderRadius: '8px', fontSize: 12, mt: 0.5 }}
                variant="outlined"
              >
                {message}
              </Alert>
            )}
          </Box>
        )}
      </Box>
    </Box>
  </Grid>
);

// eslint-disable-next-line react/no-multi-comp
const InfoRow = ({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
}) => (
  <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
    <Box
      sx={{
        alignItems: 'center',
        background: alpha('#0F8B8D', 0.08),
        borderRadius: '6px',
        display: 'flex',
        flexShrink: 0,
        height: 26,
        justifyContent: 'center',
        width: 26,
      }}
    >
      {icon}
    </Box>
    <Box>
      <Typography sx={{ color: alpha('#0F1D4D', 0.45), fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.4px', lineHeight: 1 }}>
        {label}
      </Typography>
      <Typography sx={{ color: '#0F1D4D', fontSize: 13, fontWeight: 600, lineHeight: 1.3, mt: 0.25 }}>
        {value}
      </Typography>
    </Box>
  </Box>
);

export default PatientBasicCard;
