import React, { useMemo, useState } from 'react';
import {
  Box,
  Button,
  CircularProgress,
  Grid,
  InputAdornment,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import useUser from '../../../../core/hooks/useUser';
import { useTranslation } from 'react-i18next';
import { useFormik } from 'formik';
import { useNotifier } from '../../../../core/Notifier';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import MedicalServicesOutlinedIcon from '@mui/icons-material/MedicalServicesOutlined';
import HealingIcon from '@mui/icons-material/Healing';
import PatientBasicCard from './PatientBasicCard';
import NewPatient from './NewPatient';
import {
  useGetPatientByIdQuery,
  useRegisterTreatmentMutation,
} from '../../../posApi';
import PatientHistory from './PatientHistory';
import { Privileges } from '../../../../core/types/commonType';
import { IPatientCard } from '../../../../core/Interface/patient.interface';

const TEAL = '#0F8B8D';
const NAVY = '#0F1D4D';
const MID  = '#1E3A8A';

const TreatmentsView = () => {
  const { t } = useTranslation(['common']);
  const { userHasRight } = useUser();
  const { showErrorMessage, showMessage } = useNotifier();
  const [open, setOpen] = useState(false);
  const [patientNumber, setPatientNumber] = useState<string>('');
  const [registerTreatment] = useRegisterTreatmentMutation();

  const { data, isFetching } = useGetPatientByIdQuery(
    patientNumber.split('_')[0],
    { skip: !patientNumber }
  );

  const patient = useMemo(() => {
    if (!data?.data) return { message: data?.message } as IPatientCard;
    const d = data?.data as IPatientCard;
    return { message: data?.message, ...d } as IPatientCard;
  }, [data]);

  const formik = useFormik({
    initialValues: { patientId: '', dissese: '', amount: '', medition: '' },
    onSubmit: async (values) => {
      try {
        const response = await registerTreatment({
          ...values,
          patientId: patient.id,
        }).unwrap();
        if (!response.status) {
          showErrorMessage(response.message);
        } else {
          showMessage(response.message);
          formik.resetForm();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formikNew = useFormik({
    initialValues: { patientId: '' },
    onSubmit: async (values) => {
      try {
        setPatientNumber(values.patientId);
      } catch (_e) {
        showErrorMessage('Please check your data');
      }
    },
  });

  return (
    <Box>
      {/* ── Hero banner ───────────────────────────────────────────── */}
      <Box
        sx={{
          background: `linear-gradient(135deg, ${NAVY} 0%, ${MID} 45%, ${TEAL} 100%)`,
          borderRadius: 2,
          color: '#fff',
          mb: 3,
          overflow: 'hidden',
          position: 'relative',
          px: { xs: 2, md: 3 },
          py: { xs: 1.5, md: 2 },
        }}
      >
        {/* decorative blobs */}
        <Box sx={{ background: 'rgba(255,255,255,0.07)', borderRadius: '50%', height: 220, inset: 'auto -60px -100px auto', pointerEvents: 'none', position: 'absolute', width: 220 }} />
        <Box sx={{ background: 'rgba(255,255,255,0.05)', borderRadius: '50%', height: 260, inset: '-100px auto auto 55%', pointerEvents: 'none', position: 'absolute', width: 260 }} />

        <Box
          sx={{
            alignItems: { xs: 'flex-start', sm: 'center' },
            display: 'flex',
            flexDirection: { xs: 'column', sm: 'row' },
            gap: 2,
            justifyContent: 'space-between',
            position: 'relative',
          }}
        >
          {/* title */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
            <Box
              sx={{
                alignItems: 'center',
                backdropFilter: 'blur(8px)',
                background: 'rgba(255,255,255,0.14)',
                border: '1px solid rgba(255,255,255,0.18)',
                borderRadius: '10px',
                display: 'flex',
                height: 44,
                justifyContent: 'center',
                width: 44,
              }}
            >
              <MedicalServicesOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: { xs: '1rem', md: '1.2rem' }, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1.2 }}>
                Treatments
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }}>
                Search patient · add treatment · view history
              </Typography>
            </Box>
          </Box>

          {/* search + new-patient */}
          <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5, flexWrap: 'wrap', position: 'relative' }}>
            <form onSubmit={formikNew.handleSubmit}>
              <Box sx={{ alignItems: 'center', display: 'flex', gap: 1 }}>
                <TextField
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon sx={{ color: alpha('#fff', 0.6), fontSize: 18 }} />
                      </InputAdornment>
                    ),
                    sx: {
                      color: '#fff',
                      '& .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.35)' },
                      '&:hover .MuiOutlinedInput-notchedOutline': { borderColor: 'rgba(255,255,255,0.6)' },
                      '&.Mui-focused .MuiOutlinedInput-notchedOutline': { borderColor: '#fff' },
                      '& input::placeholder': { color: 'rgba(255,255,255,0.5)' },
                    },
                  }}
                  autoComplete="off"
                  name="patientId"
                  onChange={formikNew.handleChange}
                  placeholder="Patient Number"
                  size="small"
                  sx={{ width: 240 }}
                  value={formikNew.values.patientId}
                  variant="outlined"
                />
                <Button
                  disabled={isFetching}
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    backdropFilter: 'blur(4px)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    borderRadius: '8px',
                    color: '#fff',
                    fontWeight: 700,
                    height: 40,
                    px: 2,
                    '&:hover': { background: 'rgba(255,255,255,0.28)' },
                    '&:disabled': { opacity: 0.6 },
                  }}
                  type="submit"
                  variant="outlined"
                >
                  {isFetching ? <CircularProgress
                    size={16}
                    sx={{ color: '#fff' }}
                                /> : t('common:search')}
                </Button>
              </Box>
            </form>

            {userHasRight(Privileges.PatientAdd) && (
              <Button
                onClick={() => setOpen(true)}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: `0 4px 14px ${alpha('#2563EB', 0.45)}`,
                  color: '#fff',
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                {t('common:create')} Patient
              </Button>
            )}
          </Box>
        </Box>
      </Box>

      {/* ── Patient card + treatment form ─────────────────────────── */}
      <Grid
        container
        spacing={2}
      >
        <PatientBasicCard
          address={patient?.address || ''}
          age={patient?.age}
          dateOfBirth={patient?.dateOfBirth}
          id={patient?.id}
          message={patient?.message}
          mobile={patient?.mobile}
          name={patient?.name}
          patientNumber={patient?.patientNumber}
        />

        {/* Treatment form */}
        <Grid
          item
          lg={8}
          sm={12}
          xs={12}
        >
          <Box
            sx={{
              background: '#fff',
              border: `1px solid ${alpha(TEAL, 0.18)}`,
              borderRadius: '12px',
              boxShadow: `0 4px 24px ${alpha(NAVY, 0.06)}`,
              overflow: 'hidden',
            }}
          >
            {/* card header */}
            <Box sx={{ background: `linear-gradient(90deg, ${TEAL} 0%, ${alpha(TEAL, 0.5)} 100%)`, height: 3 }} />
            <Box sx={{ px: 3, pt: 2.5, pb: 1, display: 'flex', alignItems: 'center', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: alpha(TEAL, 0.1),
                  border: `1px solid ${alpha(TEAL, 0.2)}`,
                  borderRadius: '8px',
                  display: 'flex',
                  height: 36,
                  justifyContent: 'center',
                  width: 36,
                }}
              >
                <HealingIcon sx={{ color: TEAL, fontSize: 18 }} />
              </Box>
              <Typography sx={{ color: NAVY, fontWeight: 700, fontSize: 15 }}>
                New Treatment
              </Typography>
            </Box>

            <form onSubmit={formik.handleSubmit}>
              <Box sx={{ px: 3, pb: 3, pt: 1 }}>
                <Grid
                  container
                  spacing={2}
                >
                  <Grid
                    item
                    sm={6}
                    xs={12}
                  >
                    <FormField label="Disease">
                      <TextField
                        autoComplete="off"
                        fullWidth
                        multiline
                        placeholder="Enter disease / diagnosis"
                        rows={3}
                        size="small"
                        {...formik.getFieldProps('dissese')}
                        sx={fieldSx}
                      />
                    </FormField>
                  </Grid>
                  <Grid
                    item
                    sm={6}
                    xs={12}
                  >
                    <FormField label="Medication">
                      <TextField
                        autoComplete="off"
                        fullWidth
                        multiline
                        placeholder="Enter medication prescribed"
                        rows={3}
                        size="small"
                        {...formik.getFieldProps('medition')}
                        sx={fieldSx}
                      />
                    </FormField>
                  </Grid>
                  <Grid
                    item
                    sm={6}
                    xs={12}
                  >
                    <FormField label="Amount (LKR)">
                      <TextField
                        fullWidth
                        placeholder="0.00"
                        size="small"
                        type="number"
                        {...formik.getFieldProps('amount')}
                        sx={fieldSx}
                      />
                    </FormField>
                  </Grid>
                  <Grid
                    item
                    sm={6}
                    sx={{ display: 'flex', alignItems: 'flex-end' }}
                    xs={12}
                  >
                    <Button
                      disabled={!patient?.patientNumber}
                      fullWidth
                      sx={{
                        background: patient?.patientNumber
                          ? `linear-gradient(135deg, ${TEAL} 0%, ${MID} 100%)`
                          : undefined,
                        borderRadius: '8px',
                        boxShadow: patient?.patientNumber
                          ? `0 4px 14px ${alpha(TEAL, 0.4)}`
                          : undefined,
                        color: '#fff',
                        fontWeight: 700,
                        height: 44,
                        '&:hover': {
                          background: `linear-gradient(135deg, ${MID} 0%, ${NAVY} 100%)`,
                        },
                        '&:disabled': { opacity: 0.5 },
                      }}
                      type="submit"
                      variant="contained"
                    >
                      {t('common:submit')} Treatment
                    </Button>
                  </Grid>
                </Grid>
              </Box>
            </form>
          </Box>
        </Grid>
      </Grid>

      {/* ── History ───────────────────────────────────────────────── */}
      <PatientHistory treatements={patient.treatements} />

      {open && (
        <NewPatient
          data={undefined}
          handleCloseDialog={() => setOpen(false)}
          openModel={open}
          title="Create New Patient"
        />
      )}
    </Box>
  );
};

// ── helpers ───────────────────────────────────────────────────────────────────

const fieldSx = {
  '& .MuiOutlinedInput-root': {
    borderRadius: '8px',
    backgroundColor: alpha('#0F8B8D', 0.03),
    '& fieldset': { borderColor: alpha('#0F8B8D', 0.2) },
    '&:hover fieldset': { borderColor: alpha('#0F8B8D', 0.4) },
    '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
  },
};

// eslint-disable-next-line react/no-multi-comp, max-len
const FormField = ({ label, children }: { label: string; children: React.ReactNode }) => (
  <Box>
    <Typography sx={{ color: alpha('#0F1D4D', 0.5), fontSize: 11, fontWeight: 700, mb: 0.75, textTransform: 'uppercase', letterSpacing: '0.5px' }}>
      {label}
    </Typography>
    {children}
  </Box>
);

export default TreatmentsView;
